{
  "name": "opencode-git-permissions",
  "version": "0.1.1",
  "description": "OpenCode plugin that auto-approves read-only git commands by injecting permission rules into every agent.",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/<owner>/opencode-git-permissions.git"
  },
  "bugs": {
    "url": "https://github.com/<owner>/opencode-git-permissions/issues"
  },
  "homepage": "https://github.com/<owner>/opencode-git-permissions#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "git",
    "permissions",
    "agent-safety"
  ],
  "engines": {
    "opencode": ">=1.18.18"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "prepublishOnly": "bun run build && bun run test"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.18"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.18",
    "@types/bun": "^1.3.14",
    "typescript": "^7.0.2"
  }
}
